# Cancer-specific mortality/survival meta-analysis. Source in RStudio.
if (.Platform$OS.type=='windows') try(Sys.setlocale('LC_CTYPE','English_United States.utf8'),silent=TRUE)
sf<-unlist(lapply(sys.frames(),function(x)x$ofile)); sa<-grep('^--file=',commandArgs(),value=TRUE)
ad<-if(length(sf)) dirname(normalizePath(tail(sf,1),winslash='/')) else if(length(sa)) dirname(normalizePath(sub('^--file=','',sa[1]),winslash='/')) else getwd()
setwd(ad); library(meta); library(metafor); library(grid); dir.create('previews',showWarnings=FALSE)
d<-read.csv('included_HR.csv',fileEncoding='UTF-8-BOM',check.names=FALSE)
stopifnot(nrow(d)==2L,!anyDuplicated(d$cohort),all(d$lower>0&d$lower<d$HR&d$HR<d$upper))
d$study<-paste(d$author,d$year); d$logHR<-log(d$HR); d$SE<-(log(d$upper)-log(d$lower))/(2*qnorm(.975)); d$wald_p_from_CI<-2*pnorm(-abs(d$logHR/d$SE))
fit<-function(z,ci='classic') metagen(TE=logHR,seTE=SE,studlab=study,data=z,sm='HR',common=TRUE,random=TRUE,method.tau='REML',method.random.ci=ci,adhoc.hakn.ci=if(ci=='HK')'se' else '',prediction=FALSE)
m<-fit(d); mhk<-fit(d,'HK'); chk<-rma(yi=d$logHR,sei=d$SE,method='REML',test='z')
stopifnot(abs(as.numeric(chk$b)-m$TE.random)<1e-5,abs(chk$tau2-m$tau2)<1e-5)
d$weight_fixed_percent<-100*m$w.common/sum(m$w.common); d$weight_random_percent<-100*m$w.random/sum(m$w.random)

status_page<-function(main,lines){par(mar=c(1,1,1,1),family='sans');plot.new();plot.window(xlim=c(0,1),ylim=c(0,1));rect(.015,.03,.985,.97,col='white',border='grey45');text(.5,.88,main,font=2,cex=1.35);text(.5,.80,'Style matched to the prior mortality Meta analysis',cex=.92,col='grey35');rect(.1,.23,.9,.7,col='grey97',border='grey70');ys<-seq(.61,.32,length.out=length(lines));for(i in seq_along(lines))text(.5,ys[i],lines[i],cex=.95,col=if(i==1)'firebrick3' else 'grey25')}
draw_forest<-function(){mp<-m;mp$lower<-log(d$lower);mp$upper<-log(d$upper);forest(mp,leftcols=c('studlab','TE','seTE'),leftlabs=c('Study','logHR*','SE(logHR)*'),rightcols=c('effect','ci','w.common','w.random'),rightlabs=c('HR','95% CI','Weight\n(fixed)','Weight\n(random)'),text.common='Fixed effect',text.random='Random effects (REML)',xlab='Hazard ratio (communication barrier vs reference)',smlab='Cancer-specific mortality / survival',col.square='grey65',col.square.lines='grey30',col.diamond.common='black',col.diamond.random='firebrick3',print.I2=TRUE,print.tau2=TRUE,print.Q=TRUE,print.pval.Q=TRUE,test.overall.common=TRUE,test.overall.random=TRUE,prediction=FALSE,fontsize=10,digits=3,digits.se=4,digits.tau2=4,label.left='Lower mortality hazard',label.right='Higher mortality hazard',addrows.below.overall=5,xlim=c(.1,5),at=c(.1,.25,.5,1,2,4));grid.text('Prediction interval [95%]: Not estimable (k = 2)',x=.195,y=.225,just='left',gp=gpar(fontfamily='sans',fontsize=10,fontface=2,col='royalblue3'))}
draw_funnel<-function(){par(mar=c(5.5,5,5,2),family='sans');ym<-max(d$SE)*1.25;ct<-m$TE.common;core<-range(c(d$logHR,ct+c(-1,1)*qnorm(.975)*ym));sp<-diff(core);lim<-core+c(-.55,.55)*sp;plot(NA,xlim=lim,ylim=c(ym,0),xlab='Hazard ratio (logarithmic scale)',ylab='Standard error of log(HR)',xaxt='n',main='Funnel plot: cancer-specific mortality');tk<-c(.1,.25,.5,1,2,4,10);tk<-tk[log(tk)>lim[1]&log(tk)<lim[2]];axis(1,at=log(tk),labels=tk);polygon(c(ct,ct-qnorm(.975)*ym,ct+qnorm(.975)*ym),c(0,ym,ym),col='grey94',border=NA);abline(v=ct,lty=2,col='firebrick3');lines(ct-qnorm(.975)*c(0,ym),c(0,ym),lty=3);lines(ct+qnorm(.975)*c(0,ym),c(0,ym),lty=3);points(d$logHR,d$SE,pch=21,bg='grey65',cex=1.4);text(d$logHR,d$SE*.83,d$study,cex=.78);mtext('Egger and Begg tests not estimable (k = 2)',side=3,line=.5,col='firebrick3');mtext('Two studies are insufficient to assess funnel asymmetry or publication bias',side=1,line=3.7,cex=.86);legend('bottomleft',legend=c('Fixed-effect centre','Pseudo 95% confidence limits'),lty=c(2,3),col=c('firebrick3','black'),bty='n',cex=.85)}
draw_egger<-function()status_page('Egger regression: cancer-specific mortality',c('Not estimable (k = 2)','Regression-based asymmetry tests require more independent studies.','Egger and Begg values are stored as NA; no absence of bias is inferred.'))

loo<-data.frame(omitted_id=d$study_id,omitted_study=d$study,remaining_k=1L,remaining_study=rev(d$study),HR=rev(d$HR),lower=rev(d$lower),upper=rev(d$upper),p=rev(d$original_p),tau2=NA_real_,I2_percent=NA_real_,interpretation='One published study remains; heterogeneity is not estimable')
draw_leave_one_out<-function(){par(mar=c(3,1.5,2,1.5),family='sans');plot.new();plot.window(xlim=c(0,1),ylim=c(-1.1,6.7));title('Leave-one-out sensitivity analysis',line=.1,cex.main=1.25);text(.5,6.18,'Random-effects REML | Cancer-specific mortality / survival',cex=.84,col='grey35');text(.025,5.35,'Omitted study',adj=0,font=2,cex=.86);text(.565,5.35,'Remaining estimate',font=2,cex=.86);text(.82,5.35,'HR [95% CI]',font=2,cex=.86);text(.96,5.35,'I2',font=2,cex=.86);segments(.02,5.02,.985,5.02,col='grey45');lo<-.1;hi<-5;xx<-function(h).43+(log(h)-log(lo))/(log(hi)-log(lo))*.285;yy<-c(4.25,3.25);for(i in 1:2){y<-yy[i];if(i%%2==0)rect(.02,y-.43,.985,y+.43,col='grey96',border=NA);segments(xx(1),y-.43,xx(1),y+.43,col='grey70',lty=2);text(.025,y,paste0('Omit ',loo$omitted_study[i]),adj=0,cex=.83);segments(xx(loo$lower[i]),y,xx(loo$upper[i]),y,lwd=1.35);segments(xx(loo$lower[i]),y-.11,xx(loo$lower[i]),y+.11);segments(xx(loo$upper[i]),y-.11,xx(loo$upper[i]),y+.11);points(xx(loo$HR[i]),y,pch=22,bg='grey65',cex=1.35);text(.82,y,sprintf('%.3f [%.3f, %.3f]',loo$HR[i],loo$lower[i],loo$upper[i]),cex=.79);text(.96,y,'NA',cex=.79)};segments(.02,2.55,.985,2.55,col='grey45');text(.025,1.72,'All 2 studies',adj=0,font=2,cex=.85);xm<-xx(exp(m$TE.random));xl<-xx(exp(m$lower.random));xu<-xx(exp(m$upper.random));polygon(c(xl,xm,xu,xm),c(1.72,1.92,1.72,1.52),col='firebrick3',border='firebrick3');text(.82,1.72,sprintf('%.3f [%.3f, %.3f]',exp(m$TE.random),exp(m$lower.random),exp(m$upper.random)),cex=.79,font=2);text(.96,1.72,sprintf('%.1f%%',100*m$I2),cex=.79,font=2);segments(xx(lo),.75,xx(hi),.75);for(v in c(.1,.25,.5,1,2,4)){segments(xx(v),.75,xx(v),.61);text(xx(v),.31,v,cex=.76)};text(.565,-.32,'Hazard ratio (barrier vs reference)',cex=.82);text(.025,-.72,'Each omission leaves one study; rows are remaining published HRs, not pooled estimates.',adj=0,cex=.72,col='grey35')}

target<-c('breast cancer','leukemia','prostate cancer','lung cancer','pancreatic cancer','ovarian cancer');titles<-c('Breast Cancer','Leukemia','Prostate Cancer','Lung Cancer','Pancreatic Cancer','Ovarian Cancer');elig<-data.frame(cancer=titles,studies=vapply(target,function(x)sum(d$cancer==x),integer(1)));elig$displayed<-elig$studies>0;sd<-d[d$cancer%in%target,,drop=FALSE];stopifnot(nrow(sd)==1L)
panel<-function(z){grid.roundrect(x=.5,y=.5,width=.985,height=.965,r=unit(.008,'npc'),gp=gpar(fill='white',col='grey45'));tx<-function(a,x,y,s=9,b=FALSE,j='centre',cl='black')grid.text(a,x=x,y=y,just=j,gp=gpar(fontfamily='sans',fontsize=s,fontface=if(b)2 else 1,col=cl));tx('Breast Cancer',.5,.925,12,TRUE);hd<-c('Study','logHR*','SE(logHR)*','Hazard Ratio','HR','95% CI','Weight\n(fixed)','Weight\n(random)');xs<-c(.025,.305,.385,.555,.705,.795,.883,.957);for(j in 1:8)tx(hd[j],xs[j],.827,8.3,TRUE,if(j==1)'left'else'centre');grid.lines(x=c(.012,.988),y=c(.778,.778));xp<-function(h).465+(log(h)-log(.1))/(log(5)-log(.1))*.185;grid.lines(x=rep(xp(1),2),y=c(.25,.757),gp=gpar(lty=2,col='grey50'));y<-.715;tx(z$study,.025,y,8.8,FALSE,'left');tx(sprintf('%.4f',z$logHR),.305,y,8.5);tx(sprintf('%.4f',z$SE),.385,y,8.5);grid.lines(x=xp(c(z$lower,z$upper)),y=c(y,y));grid.points(x=xp(z$HR),y=y,pch=22,size=unit(5,'mm'),gp=gpar(fill='grey65'));tx(sprintf('%.3f',z$HR),.705,y,8.5);tx(sprintf('[%.3f; %.3f]',z$lower,z$upper),.795,y,8.5);tx('100.0%',.883,y,8.5);tx('100.0%',.957,y,8.5);tx('Single study: no subgroup pooling',.025,.47,9,TRUE,'left');tx('Only prespecified six cancer types are displayed',.025,.304,8.2,FALSE,'left','royalblue3');grid.lines(x=c(.465,.65),y=c(.23,.23));for(v in c(.1,.25,.5,1,2,4)){grid.lines(x=rep(xp(v),2),y=c(.23,.21));tx(v,xp(v),.176,8)};tx('Hazard Ratio (HR)',.557,.123,8.7);tx('A',.025,.036,12,TRUE,'left')}
draw_subgroups<-function(){grid.newpage();panel(sd)}

sp<-list(forest=c(13,6.5),funnel=c(12,8),egger=c(12,8),subgroups=c(10,5),leave_one_out=c(13,6))
for(nm in names(sp)){fn<-get(paste0('draw_',nm));wh<-sp[[nm]];svg(paste0(nm,'.svg'),width=wh[1],height=wh[2],family='sans',bg='white');fn();dev.off();png(file.path('previews',paste0(nm,'.png')),width=wh[1],height=wh[2],units='in',res=125,type='cairo');fn();dev.off()}
row<-function(mm,mod){r<-grepl('Random',mod);data.frame(group='Cancer-specific mortality/survival',model=mod,k=mm$k,HR=exp(if(r)mm$TE.random else mm$TE.common),lower=exp(if(r)mm$lower.random else mm$lower.common),upper=exp(if(r)mm$upper.random else mm$upper.common),p=if(r)mm$pval.random else mm$pval.common,Q=mm$Q,Q_df=mm$df.Q,Q_p=mm$pval.Q,I2_percent=100*mm$I2,tau2=mm$tau2,prediction_lower=NA,prediction_upper=NA)}
res<-rbind(row(m,'Random effects REML (Wald)'),row(m,'Fixed effect'),row(mhk,'Random effects REML (modified HK)'))
bias<-data.frame(test=c('Egger intercept t test','Begg rank correlation'),k=2,estimate=NA,statistic=NA,df=NA,p=NA,lower=NA,upper=NA,interpretation='Not estimable/reliable with only two independent studies')
sgr<-data.frame(group='Breast Cancer',model='Single study (not pooled)',k=1,HR=sd$HR,lower=sd$lower,upper=sd$upper,p=sd$original_p,Q=NA,Q_df=NA,Q_p=NA,I2_percent=NA,tau2=NA)
sgd<-data.frame(test='Cancer-type difference test',k=1,F=NA,df1=NA,df2=NA,p=NA,interpretation='Not estimable: only breast cancer represented among six prespecified cancer types; colorectal cancer excluded by protocol')
write.csv(res,'model_results.csv',row.names=FALSE,na='NA');write.csv(bias,'bias_tests.csv',row.names=FALSE,na='NA');write.csv(elig,'subgroup_eligibility.csv',row.names=FALSE);write.csv(sgr,'subgroup_results.csv',row.names=FALSE,na='NA');write.csv(sgd,'subgroup_difference_test.csv',row.names=FALSE,na='NA');write.csv(loo,'leave_one_out.csv',row.names=FALSE,na='NA');write.csv(d,'analysis_input_with_weights.csv',row.names=FALSE,fileEncoding='UTF-8',na='NA');write.csv(sd,'subgroup_input.csv',row.names=FALSE,fileEncoding='UTF-8',na='NA')
saveRDS(list(input=d,meta=m,modified_HK=mhk,bias_tests=bias,subgroup_results=sgr,leave_one_out=loo),'analysis_objects.rds');capture.output(print(m),print(mhk),res,bias,sgr,loo,file='statistical_output.txt');capture.output(sessionInfo(),file='sessionInfo.txt')
ra<-requireNamespace('rstudioapi',quietly=TRUE)&&rstudioapi::isAvailable();writeLines(c(paste('Completed:',Sys.time()),paste('RSTUDIO:',Sys.getenv('RSTUDIO')),paste('RStudio API:',ra),paste('PID:',Sys.getpid()),paste('Working directory:',getwd()),paste('Source MD5:',unname(tools::md5sum('analysis.R')))),'execution_record.txt');writeLines(paste('Two-study cancer-specific meta-analysis completed; RStudio:',ra),'completed.txt');print(res);cat('\nCancer-specific meta-analysis and all five SVG figures completed.\n')



